ssh_bts_du = "{}{}_DU{}"                # Moler dev_name for ssh connection to DU Eg GNB0_DU0,ENB_DU0
ssh_cu_unit = "{}{}_DU{}_CU{}"          # Moler dev_name for ssh connection to Common Unit(Smod) Eg GNB0_DU0_CU1
ssh_cu_unit_lmp = "{}{}_DU{}_CU{}_LMP"  # Moler dev_name for ssh connection to Common Unit(Smod) Eg GNB0_DU0_CU1_LMP
ssh_cap_unit = "{}{}_DU{}_CU{}_CPTY{}"  # Moler dev_name for ssh connection to Capacity Unit Eg GNB0_DU0_CU0_CPTY1
syslog_bts_du = "{}{}_DU{}_SYSLOG"      # Moler dev_name for sylsog streaming from DU Eg GNB0_DU0_SYSLOG
ssh_bts_du_ru = "{}{}_DU{}_RU{}"        # Moler dev_name for ssh connection to RU Eg GNB0_DU0_RU0
rest_bts_du = "REST_{}{}_DU{}"          # Alias for rest api to DU, Eg REST_GNB0_DU0, REST_GNB0_DU1
rest_asir = "REST_{}{}_ASIR"            # Alias for rest api to DU, Eg REST_GNB0_ASIR
gui_asir = "GUI_{}{}_ASIR"              # Alias for rest api to DU, Eg REST_GNB0_ASIR
fdsw_bts_du = "FDSW_{}{}_DU{}"          # Alias for rest api to DU, Eg FDSW_GNB0_DU0, FDSW_ENB0_DU0
gui_bts_du = "GUI_{}{}_DU{}"            # Alias for GUI to DU, Eg GUI_GNB0_DU0, GUI_GNB0_DU1
ssh_cap_unit_master = "{}_MASTER".\
    format(ssh_cap_unit)                # Moler dev_name for ssh connection to Capacity Unit master subdevice Eg GNB0_DU0_CU0_CPTY1_MASTER
ssh_cap_unit_slave = "{}_SLAVE".\
    format(ssh_cap_unit)                # Moler dev_name for ssh connection to Capacity Unit slave subdevice Eg GNB0_DU0_CU0_CPTY1_SLAVE
ssh_cap_unit_loner = "{}_LONER".\
    format(ssh_cap_unit)                # Moler dev_name for ssh connection to Capacity Unit loner subdevice Eg GNB0_DU0_CU0_CPTY1_LONER

ws_du = "{}{}_DU{}_WS"                  # Moler dev_name for ssh connection to BTS Workstation eg: GNB0_DU0_WS
ssh_bts_hub = "{}{}_HUB{}"              # Moler dev_name for ssh connection to HUB Eg GNB0_HUB0

# Additional devices for CloudBts
ssh_gnb_cu = "GNB{}_CU"                 # Moler device name for ssh connection to CU Eg GNB0_CU
rest_gnb_cu = "REST_GNB{}_CU"           # Alias for rest api to CU, Eg REST_GNB0_CU, REST_GNB1_CU
gui_gnb_cu = "GUI_GNB{}_CU"             # Alias for GUI for DU, Eg GUI_GNB0_CU, GUI_GNB1_CU
